import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const TYPES = new Set(['started', 'succeeded', 'failed']);

function invalid(message) {
  throw new Error(message);
}

function isNonemptyString(value) {
  return typeof value === 'string' && value.length > 0;
}

function validateEvent(value, lineNumber) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    invalid(`Line ${lineNumber}: event must be an object`);
  }
  if (!isNonemptyString(value.id)) invalid(`Line ${lineNumber}: id must be a nonempty string`);
  if (!isNonemptyString(value.job)) invalid(`Line ${lineNumber}: job must be a nonempty string`);
  if (!Number.isSafeInteger(value.attempt) || value.attempt < 1) {
    invalid(`Line ${lineNumber}: attempt must be a positive safe integer`);
  }
  if (!Number.isSafeInteger(value.seq) || value.seq < 0) {
    invalid(`Line ${lineNumber}: seq must be a nonnegative safe integer`);
  }
  if (!TYPES.has(value.type)) invalid(`Line ${lineNumber}: invalid type`);

  // Keep only the contract fields: all other data is deliberately irrelevant.
  return { id: value.id, job: value.job, attempt: value.attempt, seq: value.seq, type: value.type };
}

function sameRequiredFields(first, second) {
  return first.job === second.job && first.attempt === second.attempt &&
    first.seq === second.seq && first.type === second.type;
}

/** Reduce a UTF-8 JSONL event log into its per-job attempt report. */
export function reduceEvents(text) {
  if (typeof text !== 'string') invalid('Input must be a string');

  const byId = new Map();
  let duplicates = 0;
  const lines = text.split(/\r?\n/);
  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index];
    if (line.trim() === '') continue;
    let parsed;
    try {
      parsed = JSON.parse(line);
    } catch {
      invalid(`Line ${index + 1}: invalid JSON`);
    }
    const event = validateEvent(parsed, index + 1);
    const prior = byId.get(event.id);
    if (prior !== undefined) {
      if (!sameRequiredFields(prior, event)) invalid(`Line ${index + 1}: conflicting duplicate id`);
      duplicates += 1;
    } else {
      byId.set(event.id, event);
    }
  }

  const jobs = new Map();
  for (const event of byId.values()) {
    let attempts = jobs.get(event.job);
    if (attempts === undefined) jobs.set(event.job, attempts = new Map());
    let record = attempts.get(event.attempt);
    if (record === undefined) attempts.set(event.attempt, record = { start: undefined, terminal: undefined });
    if (event.type === 'started') {
      if (record.start !== undefined) invalid(`Repeated start for ${event.job} attempt ${event.attempt}`);
      record.start = event;
    } else {
      if (record.terminal !== undefined) invalid(`Repeated or contradictory terminal for ${event.job} attempt ${event.attempt}`);
      record.terminal = event;
    }
  }

  const resultJobs = [];
  for (const [job, attempts] of jobs) {
    const resultAttempts = [];
    for (const [attempt, record] of attempts) {
      if (record.start === undefined && record.terminal !== undefined) invalid(`Orphan terminal for ${job} attempt ${attempt}`);
      if (record.terminal !== undefined && record.terminal.seq <= record.start.seq) {
        invalid(`Terminal must follow start for ${job} attempt ${attempt}`);
      }
      resultAttempts.push({
        attempt,
        status: record.terminal === undefined ? 'running' : record.terminal.type,
        startedSeq: record.start.seq,
        finishedSeq: record.terminal === undefined ? null : record.terminal.seq,
      });
    }
    resultAttempts.sort((left, right) => left.attempt - right.attempt);
    resultJobs.push({ job, attempts: resultAttempts });
  }
  resultJobs.sort((left, right) => left.job < right.job ? -1 : left.job > right.job ? 1 : 0);
  return { jobs: resultJobs, duplicates };
}

function runCli() {
  if (process.argv.length !== 3) throw new Error('Usage: node receipt-report.js LOGFILE');
  const text = readFileSync(process.argv[2], 'utf8');
  process.stdout.write(`${JSON.stringify(reduceEvents(text))}\n`);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  try {
    runCli();
  } catch (error) {
    process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
    process.exitCode = 2;
  }
}

